-- 独立 PostgreSQL 服务；不迁移桌面 SQLite 或既有实验云库。
CREATE TABLE IF NOT EXISTS fr_migrations (version text PRIMARY KEY, sha256 text NOT NULL, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fr_users (id text PRIMARY KEY, email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fr_sessions (digest text PRIMARY KEY, user_id text NOT NULL REFERENCES fr_users(id), csrf text NOT NULL, expires_at timestamptz NOT NULL);
CREATE TABLE fr_workspaces (id text PRIMARY KEY, title text NOT NULL, owner_id text NOT NULL REFERENCES fr_users(id));
CREATE TABLE fr_memberships (workspace_id text NOT NULL REFERENCES fr_workspaces(id), user_id text NOT NULL REFERENCES fr_users(id), role text NOT NULL CHECK(role IN ('OWNER','ADMIN','EDITOR','REVIEWER','VIEWER')), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE fr_projects (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES fr_workspaces(id), owner_id text NOT NULL REFERENCES fr_users(id), title text NOT NULL, state text NOT NULL CHECK(state IN ('STAGING','SHARED','ABORTED')), revision integer NOT NULL CHECK(revision>=0), snapshot jsonb NOT NULL, promotion_key text NOT NULL, manifest_digest text NOT NULL, initial_revision integer NOT NULL CHECK(initial_revision>=0), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(owner_id,promotion_key));
CREATE TABLE fr_grants (project_id text NOT NULL REFERENCES fr_projects(id), user_id text NOT NULL REFERENCES fr_users(id), role text NOT NULL CHECK(role IN ('EDITOR','REVIEWER','VIEWER')), can_approve boolean NOT NULL DEFAULT false, can_edit_formal boolean NOT NULL DEFAULT false, active boolean NOT NULL DEFAULT true, PRIMARY KEY(project_id,user_id));
CREATE TABLE fr_invitations (id text PRIMARY KEY, workspace_id text NOT NULL REFERENCES fr_workspaces(id), project_id text REFERENCES fr_projects(id), email text NOT NULL, role text NOT NULL CHECK(role IN ('ADMIN','EDITOR','REVIEWER','VIEWER')), digest text NOT NULL UNIQUE, expires_at timestamptz NOT NULL, state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','ACCEPTED','REVOKED')), invited_by text NOT NULL REFERENCES fr_users(id), accepted_by text REFERENCES fr_users(id));
CREATE TABLE fr_previews (project_id text NOT NULL REFERENCES fr_projects(id), photo_id text NOT NULL, object_key text NOT NULL, content_sha256 text NOT NULL, width integer NOT NULL CHECK(width BETWEEN 1 AND 2048), height integer NOT NULL CHECK(height BETWEEN 1 AND 2048), bytes integer NOT NULL CHECK(bytes BETWEEN 1 AND 8388608), PRIMARY KEY(project_id,photo_id));
CREATE TABLE fr_proposals (id text PRIMARY KEY, project_id text NOT NULL REFERENCES fr_projects(id), author_id text NOT NULL REFERENCES fr_users(id), title text NOT NULL, base_revision integer NOT NULL, revision integer NOT NULL DEFAULT 0, state text NOT NULL CHECK(state IN ('DRAFT','SUBMITTED','APPLIED','REJECTED')), operations jsonb NOT NULL, nonce text NOT NULL, decided_by text REFERENCES fr_users(id));
CREATE TABLE fr_comments (id text PRIMARY KEY, project_id text NOT NULL REFERENCES fr_projects(id), author_id text NOT NULL REFERENCES fr_users(id), body text NOT NULL, anchor jsonb NOT NULL, parent_id text REFERENCES fr_comments(id), state text NOT NULL DEFAULT 'OPEN' CHECK(state IN ('OPEN','RESOLVED','REOPENED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fr_versions (project_id text NOT NULL REFERENCES fr_projects(id), revision integer NOT NULL, snapshot jsonb NOT NULL, actor_id text NOT NULL REFERENCES fr_users(id), command_id text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,revision));
CREATE TABLE fr_commands (project_id text NOT NULL REFERENCES fr_projects(id), command_id text NOT NULL, actor_id text NOT NULL REFERENCES fr_users(id), idempotency_key text NOT NULL, payload_digest text NOT NULL, reply jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,command_id), UNIQUE(project_id,actor_id,idempotency_key));
CREATE TABLE fr_events (id bigserial PRIMARY KEY, project_id text NOT NULL REFERENCES fr_projects(id), actor_id text NOT NULL REFERENCES fr_users(id), kind text NOT NULL, revision integer NOT NULL, detail jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fr_acl_audit (id bigserial PRIMARY KEY, user_id text NOT NULL, project_id text, action text NOT NULL, allowed boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE fr_tickets (digest text PRIMARY KEY, session_digest text NOT NULL REFERENCES fr_sessions(digest) ON DELETE CASCADE, project_id text NOT NULL REFERENCES fr_projects(id), photo_id text, purpose text NOT NULL CHECK(purpose IN ('WS','PREVIEW')), expires_at timestamptz NOT NULL);
CREATE TABLE fr_drafts (project_id text NOT NULL REFERENCES fr_projects(id), user_id text NOT NULL REFERENCES fr_users(id), document bytea NOT NULL CHECK(octet_length(document)<=65536), updated_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(project_id,user_id));
CREATE INDEX ON fr_events(project_id,id);
CREATE INDEX ON fr_comments(project_id,created_at);
CREATE INDEX ON fr_tickets(expires_at);
CREATE TABLE fr_agent_scopes (id text PRIMARY KEY, digest text NOT NULL UNIQUE, project_id text NOT NULL REFERENCES fr_projects(id), session_digest text NOT NULL REFERENCES fr_sessions(digest) ON DELETE CASCADE, issued_by text NOT NULL REFERENCES fr_users(id), expires_at timestamptz NOT NULL, revoked boolean NOT NULL DEFAULT false);
CREATE FUNCTION fr_immutable() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable audit record'; END $$;
CREATE TRIGGER immutable_commands BEFORE UPDATE OR DELETE ON fr_commands FOR EACH ROW EXECUTE FUNCTION fr_immutable();
CREATE TRIGGER immutable_versions BEFORE UPDATE OR DELETE ON fr_versions FOR EACH ROW EXECUTE FUNCTION fr_immutable();
CREATE TRIGGER immutable_events BEFORE UPDATE OR DELETE ON fr_events FOR EACH ROW EXECUTE FUNCTION fr_immutable();
